        private static BossMoveProfile PrimusProfile(string suffix, string ja, string en, string zh, BossChannelDef[] channels, params BossAction[] actions)
            => new BossMoveProfile("boss_primus_aeron." + suffix, PrimusSetId, new Txt(ja, en, zh), channels, actions);
        private static BossAction PrimusFan(BossEvent trigger, string channel, int cooldown, int range, int angle, BossElement element = BossElement.Neutral, int count = 1)
            => new BossAction(trigger, BossMechanism.ShapeAttack, BossPayload.Damage, channel, BossShape.Fan,
                cooldownMillis: cooldown,intervalMillis:count == 2 ? BossPrimusBalance.FanDoubleIntervalMillis : 0, count: count,maxTargets:BossPrimusBalance.FanMaxTargets,maxInstances:BossPrimusBalance.FanMaxInstances,
                rangeMilli: range, angleMilli: angle, element: element);
        private static BossAction PrimusLight(BossEvent trigger, string channel, int cooldown, int maxTargets = BossPrimusBalance.LightMaxTargets, int lifetime = BossPrimusBalance.LightDefaultLifetimeMillis)
            => new BossAction(trigger, BossMechanism.Projectile, BossPayload.Damage, channel,
                cooldownMillis: cooldown, lifetimeMillis: lifetime, maxTargets: maxTargets,maxInstances:BossPrimusBalance.LightMaxInstances,rangeMilli:BossPrimusBalance.LightRangeMilli,widthMilli:BossPrimusBalance.LightWidthMilli,speedMilli:BossPrimusBalance.LightSpeedMilli,hitGateMillis:BossPrimusBalance.LightHitGateMillis, firstHitOnly: true, element: BossElement.Light);
        private static BossAction PrimusShield(BossEvent trigger, string channel, int cooldown, int lifetime)
            => new BossAction(trigger, BossMechanism.Defense, BossPayload.Shield, channel, cooldownMillis: cooldown,
                lifetimeMillis: lifetime,maxTargets:BossPrimusBalance.ShieldMaxTargets,maxInstances:BossPrimusBalance.ShieldMaxInstances, followOwner: true);

        internal static BossMoveProfile[] CreatePrimusMoves() => new[]
        {
            PrimusProfile("weapon", "通常攻撃が初めて命中したとき、前方3m・角度90°の扇状の範囲に、攻撃力・魔力の高い方の18%の無属性ダメージを与える。敵1体につき1回命中し、最大8体まで。再発動まで4秒かかる。", "On your basic attack's first hit, deal Neutral damage equal to 18% of whichever is higher: your Attack or Ability Power, in a forward 90° fan extending 3m. Hits each enemy once, up to 8 enemies. Cooldown: 4 seconds.", "通常攻击首次命中时，对前方3m、角度90°的扇形范围造成相当于攻击力与法术强度中较高一方18%的无属性伤害。每名敌人命中1次，最多8名。冷却4秒。",
                new[] { C("PrimusForceStrike",BossPrimusBalance.PrimusForceStrikeValue,BossPrimusBalance.PrimusForceStrikeCap) }, PrimusFan(BossEvent.MainHit,"PrimusForceStrike",BossPrimusBalance.WeaponA0CooldownMillis,BossPrimusBalance.WeaponA0RangeMilli,BossPrimusBalance.WeaponA0AngleMilli)),
            PrimusProfile("armor", "敵の攻撃でダメージを受けた後、最大HPの8%の障壁を得る。障壁は3秒かけて徐々に減っていき、無敵時間はない。再発動まで12秒かかる。", "After taking damage from an enemy attack, gain a shield equal to 8% of your maximum HP that gradually decays over 3 seconds. Cooldown: 12 seconds. Does not grant invulnerability.", "受到敌人攻击的伤害后，获得相当于最大HP8%的护盾，护盾在3秒内逐渐衰减。冷却12秒，不会获得无敌。",
                new[] { C("PrimusRageShield",BossPrimusBalance.PrimusRageShieldValue,BossPrimusBalance.PrimusRageShieldCap,BossCoefficientKind.Shield) }, PrimusShield(BossEvent.NativeDamageTaken,"PrimusRageShield",BossPrimusBalance.ArmorA0CooldownMillis,BossPrimusBalance.ArmorA0LifetimeMillis)),
            PrimusProfile("charm", "記憶を使ったとき、その方向へ光弾を1発発射する。光弾の射程は8m、弾速は12m/秒、幅は0.4m。初弾が着弾した後、3m以内にいる未命中の敵へ0.15秒間隔で最大2回跳躍し、それぞれ攻撃力・魔力の高い方の8%の光属性ダメージを与える。命中するのは最大3体の異なる敵で、持続は1.5秒。再発動まで7秒かかる。", "When you use a memory, fire 1 light projectile in its direction, with an 8m range, a speed of 12m per second, and a width of 0.4m. After its first impact, it jumps up to 2 times to enemies within 3m that it has not hit, at 0.15-second intervals. Each hit deals Light damage equal to 8% of whichever is higher: your Attack or Ability Power. Hits up to 3 different enemies and lasts 1.5 seconds. Cooldown: 7 seconds.", "使用记忆时，向其方向发射1枚光弹，射程8m，弹速12m/秒，宽0.4m。首次命中后，以0.15秒的间隔向3m以内尚未命中的敌人最多跳跃2次，每次造成相当于攻击力与法术强度中较高一方8%的光属性伤害。最多命中3名不同敌人，持续1.5秒。冷却7秒。",
                new[] { C("PrimusAdaptChain",BossPrimusBalance.PrimusAdaptChainValue,BossPrimusBalance.PrimusAdaptChainCap) }, PrimusLight(BossEvent.MemoryUse,"PrimusAdaptChain",BossPrimusBalance.CharmA0CooldownMillis,BossPrimusBalance.CharmA0MaxTargets,BossPrimusBalance.CharmA0LifetimeMillis)),
            PrimusProfile("head", "通常攻撃が初めて命中したとき、前方3m・角度120°の扇状の範囲へ、0秒後と0.25秒後に闇の斬撃を放ち、それぞれ攻撃力・魔力の高い方の10%の闇属性ダメージを与える。同じ敵には合計20%で、各回に最大8体まで命中する。再発動まで5秒かかる。", "On your basic attack's first hit, release Dark slashes at 0 and 0.25 seconds in a forward 120° fan extending 3m. Each deals Dark damage equal to 10% of whichever is higher: your Attack or Ability Power (20% total per enemy), hitting up to 8 enemies per slash. Cooldown: 5 seconds.", "通常攻击首次命中时，分别于0秒后和0.25秒后，向前方3m、角度120°的扇形范围释放暗之斩击，各造成相当于攻击力与法术强度中较高一方10%的暗属性伤害（同一敌人合计20%），每次最多命中8名敌人。冷却5秒。",
                new[] { C("PrimusRageBlades",BossPrimusBalance.PrimusRageBladesValue,BossPrimusBalance.PrimusRageBladesCap) }, PrimusFan(BossEvent.MainHit,"PrimusRageBlades",BossPrimusBalance.HeadA0CooldownMillis,BossPrimusBalance.HeadA0RangeMilli,BossPrimusBalance.HeadA0AngleMilli,BossElement.Dark,BossPrimusBalance.HeadA0Count)),
            PrimusProfile("hands", "記憶を使ったとき、指定位置（自身から6m以内）に予告を出し、0.5秒後に半径2mの範囲へ攻撃力・魔力の高い方の18%の火属性ダメージを1回与える。最大8体まで命中し、スタンはしない。再発動まで8秒かかる。", "When you use a memory, after a 0.5-second warning at the selected location within 6m of you, deal Fire damage equal to 18% of whichever is higher: your Attack or Ability Power, once within a 2m radius. Hits up to 8 enemies. Cooldown: 8 seconds. Does not stun.", "使用记忆时，在指定位置（自身6m以内）显示0.5秒的预警，随后对半径2m范围造成1次相当于攻击力与法术强度中较高一方18%的火属性伤害。最多命中8名敌人。冷却8秒，不会施加眩晕。",
                new[] { C("PrimusDoomImpact",BossPrimusBalance.PrimusDoomImpactValue,BossPrimusBalance.PrimusDoomImpactCap) },
                new BossAction(BossEvent.MemoryUse,BossMechanism.ShapeAttack,BossPayload.Damage,"PrimusDoomImpact",anchor:BossAnchor.Cursor,cooldownMillis:BossPrimusBalance.HandsA0CooldownMillis,delayMillis:BossPrimusBalance.HandsA0DelayMillis,maxTargets:BossPrimusBalance.HandsA0MaxTargets,maxInstances:BossPrimusBalance.HandsA0MaxInstances,radiusMilli:BossPrimusBalance.HandsA0RadiusMilli,rangeMilli:BossPrimusBalance.HandsA0RangeMilli,element:BossElement.Fire)),
            PrimusProfile("feet", "移動が終わったとき、着地点の前方2.5m・角度120°の扇状の範囲へ、0秒後と0.25秒後に冷気の斬撃を放ち、それぞれ攻撃力・魔力の高い方の10%の冷気属性ダメージを与える。同じ敵には合計20%で、各回に最大8体まで命中する。再発動まで7秒かかる。", "When you finish moving, release Cold slashes at 0 and 0.25 seconds from your landing position in a forward 120° fan extending 2.5m. Each deals Cold damage equal to 10% of whichever is higher: your Attack or Ability Power (20% total per enemy), hitting up to 8 enemies per slash. Cooldown: 7 seconds.", "移动结束时，分别于0秒后和0.25秒后，从落地地点向前方2.5m、角度120°的扇形范围释放冰斩击，各造成相当于攻击力与法术强度中较高一方10%的冰属性伤害（同一敌人合计20%），每次最多命中8名敌人。冷却7秒。",
                new[] { C("PrimusIceclawCuts",BossPrimusBalance.PrimusIceclawCutsValue,BossPrimusBalance.PrimusIceclawCutsCap) }, PrimusFan(BossEvent.MovementCompleted,"PrimusIceclawCuts",BossPrimusBalance.FeetA0CooldownMillis,BossPrimusBalance.FeetA0RangeMilli,BossPrimusBalance.FeetA0AngleMilli,BossElement.Cold,BossPrimusBalance.FeetA0Count)),
            PrimusProfile("stage2", "通常攻撃の命中、記憶の使用、移動の完了のいずれかを行うと、対応する相（Force / Adapt / Rage）が選択される。入力間隔は0.5秒。技は1つずつ放ち、共通の再発動まで3秒かかる。通常攻撃が命中したとき（Force）は、前方3m・角度90°の扇状に攻撃力・魔力の高い方の12%の無属性ダメージを与える。記憶を使ったとき（Adapt）は、射程8m・弾速12m/秒・幅0.4mの光弾で、攻撃力・魔力の高い方の12%の光属性ダメージを与える。移動が終わったとき（Rage）は、着地点の半径2mに攻撃力・魔力の高い方の12%の闇属性ダメージを与える。どの技も最大8体まで命中する。共通の再発動待ちの間は相の切り替えだけが行われ、技の発動や予約はされない。", "A basic attack hit, memory use, or completed movement selects Force, Adapt, or Rage respectively. Actions that select a phase must be at least 0.5 seconds apart. When the shared 3-second Cooldown is ready, release the corresponding technique: Force deals Neutral damage in a forward 90° fan extending 3m; Adapt fires a light projectile with an 8m range, a speed of 12m per second, and a width of 0.4m; Rage deals Dark damage within a 2m radius of your landing position. Each technique deals damage equal to 12% of whichever is higher: your Attack or Ability Power, to up to 8 enemies. During the shared Cooldown, actions only change your phase; they do not activate or queue a technique.", "通常攻击命中、使用记忆或移动结束时，分别选择对应的相态（Force / Adapt / Rage），相态选择的输入间隔至少为0.5秒。共享的3秒冷却结束后，释放对应招式：Force对前方3m、角度90°的扇形范围造成无属性伤害；Adapt发射射程8m、弹速12m/秒、宽0.4m的光弹；Rage对落地地点半径2m范围造成暗属性伤害。每种招式均造成相当于攻击力与法术强度中较高一方12%的伤害，最多命中8名敌人。共享冷却期间，行动仅切换相态，不会发动或预约招式。",
                new[] { C("PrimusPhaseTechnique",BossPrimusBalance.PrimusPhaseTechniqueValue,BossPrimusBalance.PrimusPhaseTechniqueCap) },
                new BossAction(BossEvent.MainHit,BossMechanism.Ledger,BossPayload.Mode,cooldownMillis:BossPrimusBalance.Stage2A0CooldownMillis,count:BossPrimusBalance.Stage2A0Count,maxTargets:BossPrimusBalance.Stage2A0MaxTargets,maxInstances:BossPrimusBalance.Stage2A0MaxInstances),
                PrimusFan(BossEvent.MainHit,"PrimusPhaseTechnique",BossPrimusBalance.Stage2A1CooldownMillis,BossPrimusBalance.Stage2A1RangeMilli,BossPrimusBalance.Stage2A1AngleMilli),
                PrimusLight(BossEvent.MemoryUse,"PrimusPhaseTechnique",BossPrimusBalance.Stage2A2CooldownMillis),
                new BossAction(BossEvent.MovementCompleted,BossMechanism.ShapeAttack,BossPayload.Damage,"PrimusPhaseTechnique",cooldownMillis:BossPrimusBalance.Stage2A3CooldownMillis,maxTargets:BossPrimusBalance.Stage2A3MaxTargets,maxInstances:BossPrimusBalance.Stage2A3MaxInstances,radiusMilli:BossPrimusBalance.Stage2A3RadiusMilli,element:BossElement.Dark)),
            PrimusProfile("stage3", "移動が終わったとき、その移動の出発点に相紋を1個残す。相紋は4秒間持続し、新しく移動が終わると上書きされる。次に発動する通常攻撃または記憶使用による相技は、自身から6m以内にある相紋を消費し、0.35秒の予告の後、自身の代わりに相紋の位置から技を放つ。自身との二重発射やダメージの増加はなく、6m範囲外の相紋は破棄されて、自身を起点として発射する。", "When you finish moving, leave 1 phase glyph at your departure point for 4 seconds. Finishing another movement replaces it. The next phase technique activated by a basic attack or memory use consumes a glyph within 6m of you and, after a 0.35-second warning, fires from the glyph instead of from you. It does not fire twice or increase damage. A glyph more than 6m away is discarded, and the technique fires from you.", "移动结束时，在出发地点留下1个相纹，持续4秒。再次移动结束会替换旧相纹。下一次由通常攻击或使用记忆发动的相态招式，会消耗自身6m以内的相纹，经过0.35秒预警后，从相纹位置代替自身释放。不会双重发射或增加伤害。超过6m的相纹会被丢弃，招式从自身释放。",
                new[] { C("PrimusGlyphReach",BossPrimusBalance.PrimusGlyphReachValue,BossPrimusBalance.PrimusGlyphReachCap,BossCoefficientKind.Distance) },
                new BossAction(BossEvent.MovementCompleted,BossMechanism.Ledger,BossPayload.Mark,delayMillis:BossPrimusBalance.Stage3A0DelayMillis,lifetimeMillis:BossPrimusBalance.Stage3A0LifetimeMillis,maxTargets:BossPrimusBalance.Stage3A0MaxTargets,maxInstances:BossPrimusBalance.Stage3A0MaxInstances,rangeMilli:BossPrimusBalance.Stage3A0RangeMilli,replaceOldest:true)),
            PrimusProfile("stage6", "8秒以内に、通常攻撃の命中、記憶の使用、移動の完了という異なる3種類の行動を行うと、「三相合流」が発動する。再発動まで18秒かかり、同じ行動を重ねて入力しても進行せず、時間も延びない。成立させた行動の通常の相技を、共通の再発動待ちの間であっても置き換えて発動する。相紋が自身から6m以内にあればその位置から、なければ自身を起点として（起点と向きは固定）、0秒後、0.3秒後、0.6秒後に、順に3つの攻撃を放つ。攻撃は前方4m・角度90°の扇状の無属性攻撃、前方8m・幅0.6mの直線上の光属性攻撃、半径2.5mの円形の闇属性攻撃で、それぞれ攻撃力・魔力の高い方の30%のダメージを与える。各攻撃は最大8体に命中し、同じ敵には最大で合計90%（上限100%）まで与える。同時に、最大HPの38%（上限40%）の障壁を得て、障壁は6秒かけて直線的に減っていく。成立したときに印と相紋を消費する。再発動待ちの間に成立した場合は破棄される。連携、特定の記憶、召喚、HPの条件などは必要ない。", "Perform all 3 different actions within 8 seconds—a basic attack hit, memory use, and completed movement—to activate Three-Phase Confluence. Cooldown: 18 seconds. Repeating an action does not advance the sequence or extend its time limit. Confluence replaces the completing action's ordinary phase technique, even during the shared Cooldown. With its starting point and direction fixed, it fires from a phase glyph within 6m of you, or from you if there is none: at 0 seconds, a Neutral attack in a forward 90° fan extending 4m; at 0.3 seconds, a Light attack along a line 8m long and 0.6m wide; at 0.6 seconds, a Dark attack within a 2.5m radius. Each deals damage equal to 30% of whichever is higher: your Attack or Ability Power, to up to 8 enemies (up to 90% total per enemy, capped at 100%). At the same time, gain a shield equal to 38% of your maximum HP (capped at 40%) that decays at a constant rate over 6 seconds. Completion consumes the marks and phase glyph. A sequence completed during Confluence's Cooldown is discarded. No link, specific memory, summon, or HP condition is required.", "8秒内完成通常攻击命中、使用记忆和移动结束这3种不同行动时，发动“三相合流”。冷却18秒。重复同一行动不会推进顺序或延长时限。合流会替换完成顺序的行动所对应的普通相态招式，即使处于共享冷却期间也会发动。起点和方向固定，从自身6m以内的相纹处释放，没有相纹则从自身释放：0秒后对前方4m、角度90°的扇形范围发动无属性攻击；0.3秒后沿长8m、宽0.6m的直线发动光属性攻击；0.6秒后对半径2.5m范围发动暗属性攻击。每次造成相当于攻击力与法术强度中较高一方30%的伤害，最多命中8名敌人（同一敌人合计最多90%，上限100%）。同时获得相当于最大HP38%（上限40%）的护盾，在6秒内匀速衰减。完成顺序时消耗印记和相纹。在合流冷却期间完成的顺序会被丢弃。无需连携、特定记忆、召唤物或HP条件。",
                new[] { C("PrimusConfluence",BossPrimusBalance.PrimusConfluenceValue,BossPrimusBalance.PrimusConfluenceCap), C("PrimusConfluenceShield",BossPrimusBalance.PrimusConfluenceShieldValue,BossPrimusBalance.PrimusConfluenceShieldCap,BossCoefficientKind.Shield) },
                new BossAction(BossEvent.MainHit,BossMechanism.Ledger,BossPayload.Mark,cooldownMillis:BossPrimusBalance.Stage6A0CooldownMillis,lifetimeMillis:BossPrimusBalance.Stage6A0LifetimeMillis,count:BossPrimusBalance.Stage6A0Count,maxTargets:BossPrimusBalance.Stage6A0MaxTargets,maxInstances:BossPrimusBalance.Stage6A0MaxInstances),
                PrimusFan(BossEvent.Clock,"PrimusConfluence",BossPrimusBalance.Stage6A1CooldownMillis,BossPrimusBalance.Stage6A1RangeMilli,BossPrimusBalance.Stage6A1AngleMilli),
                new BossAction(BossEvent.Clock,BossMechanism.ShapeAttack,BossPayload.Damage,"PrimusConfluence",BossShape.Line,delayMillis:BossPrimusBalance.Stage6A2DelayMillis,maxTargets:BossPrimusBalance.Stage6A2MaxTargets,maxInstances:BossPrimusBalance.Stage6A2MaxInstances,rangeMilli:BossPrimusBalance.Stage6A2RangeMilli,widthMilli:BossPrimusBalance.Stage6A2WidthMilli,element:BossElement.Light),
                new BossAction(BossEvent.Clock,BossMechanism.ShapeAttack,BossPayload.Damage,"PrimusConfluence",delayMillis:BossPrimusBalance.Stage6A3DelayMillis,maxTargets:BossPrimusBalance.Stage6A3MaxTargets,maxInstances:BossPrimusBalance.Stage6A3MaxInstances,radiusMilli:BossPrimusBalance.Stage6A3RadiusMilli,element:BossElement.Dark),
                PrimusShield(BossEvent.Clock,"PrimusConfluenceShield",BossPrimusBalance.Stage6A4CooldownMillis,BossPrimusBalance.Stage6A4LifetimeMillis)),
        };

